#define FLAG_A 0x10
#define FLAG_B 0x01

unsigned int flags = 0x11;

// Bitwise AND (&) binds tighter than Logical OR (||).
// WRONG: Tests if (flags & FLAG_A) is true OR if FLAG_B is non-zero (always true).
int bad_check = flags & FLAG_A || FLAG_B;

// CORRECT: Uses parentheses to enforce intended logical check (A OR B set).
int good_check = (flags & FLAG_A) || (flags & FLAG_B);

// Combining shift and ternary (Shift > Relational > Ternary)
int value = 0x80; // MSB set
// Check if 7th bit is set, result is 1 or 0
int sign_bit = (value >> 7) & 1;

// Conditional mask application
unsigned int result = sign_bit ? (value | 0xFF) : (value & 0x0F);
